effect.shader:
const float TAU = 6.2831853;

/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Sobel: magnitude do gradiente da luma com um kernel 3×3. */
float sobelAqui(vec2 uv) {
    vec2 px = 1.0 / vec2(textureSize(inputImg, 0));

    float tl = luma(texture(inputImg, uv + vec2(-px.x,  px.y)).rgb);
    float t  = luma(texture(inputImg, uv + vec2( 0.0,   px.y)).rgb);
    float tr = luma(texture(inputImg, uv + vec2( px.x,  px.y)).rgb);
    float l  = luma(texture(inputImg, uv + vec2(-px.x,  0.0 )).rgb);
    float r  = luma(texture(inputImg, uv + vec2( px.x,  0.0 )).rgb);
    float bl = luma(texture(inputImg, uv + vec2(-px.x, -px.y)).rgb);
    float b  = luma(texture(inputImg, uv + vec2( 0.0,  -px.y)).rgb);
    float br = luma(texture(inputImg, uv + vec2( px.x, -px.y)).rgb);

    float gx = -tl - 2.0 * l - bl + tr + 2.0 * r + br;
    float gy = -tl - 2.0 * t - tr + bl + 2.0 * b + br;
    return length(vec2(gx, gy));
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    float borda = sobelAqui(acScreenNorm) * edgeStrength;
    borda = clamp(borda, 0.0, 1.0);

    // Halo: média do sobel em volta, num círculo de 8 amostras.
    float halo = 0.0;
    vec2 px = 1.0 / vec2(textureSize(inputImg, 0));
    for (int i = 0; i < 8; i++) {
        float a = TAU * float(i) / 8.0;
        vec2 d = vec2(cos(a), sin(a)) * haloRadius * px;
        halo += sobelAqui(acScreenNorm + d) * edgeStrength;
    }
    halo = clamp(halo / 8.0, 0.0, 1.0) * haloStrength;

    vec3 fundo = mix(original.rgb, vec3(0.0), darken);
    vec3 cor = fundo + tubeColor.rgb * (borda + halo);
    cor = clamp(cor, 0.0, 1.0);

    fragColor = vec4(cor, original.a);
}
